[2845] = "반올림된 경과 시간 구간의 원래 개수이며, 결과가 단독 0이면 생략됩니다.",
-- 169b03f3 English: Packaged helper from Conditions/spatial.lua.
[2846] = "Conditions/spatial.lua에서 제공하는 도우미입니다.",
-- 18a2dc4d English: Packaged helper from utils.lua.
[2847] = "utils.lua에서 제공하는 도우미입니다.",
