--     matches.
[3032] = "원래의 내림 동등 또는 정확한 숫자 표기 조건식이 일치하는지 여부.",
-- 8c0b7ad7 English: Whether the text begins with the exact prefix.
[3033] = "텍스트가 정확한 접두사로 시작하는지 여부.",
-- 37054b01 English: Whether the text ends with the exact suffix.
[3034] = "텍스트가 정확한 접미사로 끝나는지 여부.",
-- 2ae8305f English: With restricted-value only: isActive, true while a cooldown (its own or the
--     global one) is running.
[3035] = "restricted-value일 때만: isActive, 재사용 대기시간(자체 또는 전역)이 진행 중인 동안 true.",
-- 08c56f26 English: With restricted-value only: isEnabled, false while the cooldown is on hold.
[3036] = "restricted-value일 때만: isEnabled, 재사용 대기시간이 보류 중인 동안 false.",
-- 11f0d805 English: With restricted-value only: isOnGCD, true when the running cooldown is the
--     global cooldown; may be nil.
[3037] = "restricted-value일 때만: isOnGCD, 진행 중인 재사용 대기시간이 전역 재사용 대기시간이면 true. nil일 수 있습니다.",
-- 303e2b6b English: Work-limit, data or arithmetic availability reason for nil rate/age.
[3038] = "nil인 변화율/경과 시간에 대한 작업 한도, 데이터 또는 산술 사용 불가 이유.",
-- 01efc08d English: Wrap text at whitespace boundaries near a target column count. Long words are
--     retained intact.
[3039] = "목표 열 수 근처의 공백 경계에서 텍스트를 줄바꿈합니다. 긴 단어는 자르지 않습니다.",
-- 07e1e312 English: mana selects the explicit live Mana enum; current reads and forwards the actual
--     UnitPowerType identity, including Mana zero.
[3040] = "mana는 명시적인 실시간 Mana 열거형을 선택하고, current는 Mana 0을 포함해 실제 UnitPowerType 식별을 읽어 전달합니다.",
-- c383f3b4 English: noheals selects damage only; nodmg selects healing only; other readable values
